import { useNavigate } from 'react-router-dom';
import { useState } from 'react';
import AdminOverview from './components/AdminOverview';
import InventoryManager from './components/InventoryManager';
import OrderManager from './components/OrderManager';
import MaintenanceManager from './components/MaintenanceManager';
import InvoiceUploader from './components/InvoiceUploader';
import QRCodeGenerator from './components/QRCodeGenerator';


const AdminDashboardPage = () => {
  const navigate = useNavigate();
   const [activeSection, setActiveSection] = useState('overview');

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    navigate('/login');
  }

   const renderSection = () => {
    switch (activeSection) {
      case 'overview':
        return <AdminOverview />;
      case 'inventory':
        return <InventoryManager />;
      case 'orders':
        return <OrderManager />;
      case 'maintenance':
        return <MaintenanceManager />;
      case 'invoices':
        return <InvoiceUploader />;
      case 'qrcodes':
        return <QRCodeGenerator />;
      default:
        return <AdminOverview />;
    }
  }

  return (
  <div>
    <h1>Admin Dashboard</h1>
     <nav>
        <button onClick={() => setActiveSection('overview')}>Dashboard</button>
        <button onClick={() => setActiveSection('inventory')}>Inventory</button>
        <button onClick={() => setActiveSection('orders')}>Orders</button>
        <button onClick={() => setActiveSection('maintenance')}>Maintenance</button>
        <button onClick={() => setActiveSection('invoices')}>Invoices</button>
        <button onClick={() => setActiveSection('qrcodes')}>QR Codes</button>
        <button onClick={() => setActiveSection('partners')}>Partners</button>
      </nav>
      <div>{renderSection()}</div>
    <button onClick={handleLogout}>Log Out</button>
  </div>
  );
};
export default AdminDashboardPage;
